<?php
include '../includes/session.php';include '../database/config.php';include '../includes/helpers.php';require_once '../services/CertificateService.php';requireAdmin();requirePermission('certificates.manage');$service=new CertificateService($conn,dirname(__DIR__));$actor=(int)$_SESSION['user_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){requireValidCsrfToken();try{$action=(string)($_POST['action']??'');if($action==='create_draft'){$id=$service->draft((string)$_POST['certificate_type'],(int)$_POST['record_id'],!empty($_POST['request_id'])?(int)$_POST['request_id']:null,$actor);redirectWithNotification('?focus='.$id,'Controlled certificate draft created.','success');}if(in_array($action,['submit_review','approve','release'],true)){if(in_array($action,['approve','release'],true)&&!hasPermission('certificates.issue'))throw new DomainException('You do not have certificate issuance permission.');$service->advance((int)$_POST['certificate_id'],$action,$actor,(string)($_POST['reason']??''));redirectWithNotification('certificate-workflow.php','Certificate moved to the next controlled state.','success');}if($action==='issue'){if(!hasPermission('certificates.issue'))throw new DomainException('You do not have certificate issuance permission.');$result=$service->issue((int)$_POST['certificate_id'],$actor);redirectWithNotification('certificate-workflow.php','Certificate '.$result['number'].' issued with SHA-256 integrity protection.','success');}if($action==='revoke'){if(!hasPermission('certificates.revoke'))throw new DomainException('You do not have revocation permission.');$service->revoke((int)$_POST['certificate_id'],(string)($_POST['reason']??''),$actor);redirectWithNotification('certificate-workflow.php','Certificate revoked.','success');}if($action==='reissue'){if(!hasPermission('certificates.issue'))throw new DomainException('You do not have issuance permission.');$new=$service->reissue((int)$_POST['certificate_id'],(string)($_POST['reason']??''),$actor);redirectWithNotification('?focus='.$new,'Linked reissue draft created.','success');}throw new DomainException('Invalid certificate action.');}catch(Throwable$e){redirectWithNotification('certificate-workflow.php',$e->getMessage(),'error');}}
$rows=$conn->query("SELECT c.*,u.fullname issuer FROM certificate_issuances c LEFT JOIN users u ON u.id=c.issued_by ORDER BY c.certificate_id DESC LIMIT 200")->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Certificate workflow</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="../assets/css/holy-theme.css"></head><body><?php include '../includes/admin-sidebar.php';?><main class="admin-content p-4" style="margin-left:280px"><div class="d-flex justify-content-between"><div><h1>Certificate workflow</h1><p class="text-muted">Draft → Review → Approval → Issue → Release. Preview never issues.</p></div><a class="btn btn-primary align-self-start" href="certificate-generator.php">New certificate preview</a></div><div class="card mt-3"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>ID / Number</th><th>Type</th><th>Name</th><th>Status</th><th>Integrity</th><th>Action</th></tr></thead><tbody><?php foreach($rows as$c):?><tr id="certificate-<?php echo(int)$c['certificate_id'];?>"><td>#<?php echo(int)$c['certificate_id'];?><br><small><?php echo e($c['certificate_number']??'Not assigned');?></small></td><td><?php echo e(str_replace('_',' ',$c['certificate_type']));?></td><td><?php echo e($c['issued_to']);?></td><td><span class="badge text-bg-<?php echo $c['status']==='revoked'?'danger':(in_array($c['status'],['issued','released'],true)?'success':'warning');?>"><?php echo e($c['status']);?></span></td><td><?php if($c['certificate_hash']):?><code title="<?php echo e($c['certificate_hash']);?>"><?php echo e(substr($c['certificate_hash'],0,12));?>…</code><?php else:?>—<?php endif;?></td><td><div class="d-flex flex-wrap gap-1"><?php $next=['draft'=>'submit_review','review'=>'approve','approval'=>'issue','issued'=>'release'][$c['status']]??null;if($next):?><form method="post"><?php echo csrfInput();?><input type="hidden" name="certificate_id" value="<?php echo(int)$c['certificate_id'];?>"><button class="btn btn-sm btn-primary" name="action" value="<?php echo e($next);?>"><?php echo e(ucwords(str_replace('_',' ',$next)));?></button></form><?php endif;?><?php if(!empty($c['pdf_path'])):?><a class="btn btn-sm btn-outline-success" href="certificate-file.php?id=<?php echo(int)$c['certificate_id'];?>">Download PDF</a><?php endif;?><?php if(in_array($c['status'],['issued','released'],true)):?><form method="post" class="d-flex"><?php echo csrfInput();?><input type="hidden" name="certificate_id" value="<?php echo(int)$c['certificate_id'];?>"><input class="form-control form-control-sm" name="reason" required minlength="5" placeholder="Revocation reason"><button class="btn btn-sm btn-danger" name="action" value="revoke">Revoke</button></form><?php elseif($c['status']==='revoked'):?><form method="post" class="d-flex"><?php echo csrfInput();?><input type="hidden" name="certificate_id" value="<?php echo(int)$c['certificate_id'];?>"><input class="form-control form-control-sm" name="reason" required minlength="5" placeholder="Reissue reason"><button class="btn btn-sm btn-warning" name="action" value="reissue">Reissue</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>
